import { mapState } from "vuex";
import { activityFrameList,activityFrameStatus } from "@/api/marketing";
import timeOptions from "@/utils/timeOptions";
export default {
  data() {
    return {
      options: timeOptions,
      timeVal: [],
      dataTimeVal: [],
      formValidate: {
        name: "",
        status: "",
        time: "",
        create_time: "",
        page: 1,
        limit: 15,
      },
      list: [
        {status:0,title:'未开始'},
        {status:1,title:'进行中'},
        {status:-1,title:'已结束'}
      ],
      columns: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "活动名称",
          key: "name",
          minWidth: 170,
        },
        {
          title: "活动时间",
          slot: "time",
          minWidth: 260,
        },
        {
          title: "参与商品数",
          key: "product_count",
          minWidth: 100,
        },
        {
          title: "活动状态",
          slot: "start_status",
          minWidth: 100,
        },
        {
          title: "是否开启",
          slot: "status",
          minWidth: 100,
        },
        {
          title: "创建时间",
          key: "add_time",
          minWidth: 140,
        },
        {
          title: "操作",
          slot: "action",
          minWidth: 110,
          fixed: 'right'
        },
      ],
      dataList: [],
      loading: false,
      total: 0,
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.activityFrameList();
  },
  methods: {
    createTime(e) {
      this.timeVal = e;
      this.formValidate.create_time = this.timeVal.join("-");
    },
    dataTime(e){
      this.dataTimeVal = e;
      this.formValidate.time = this.dataTimeVal.join("-");
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `marketing/activity_frame/del/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData).then((res) => {
        this.$Message.success(res.msg);
        this.dataList.splice(num, 1);
        if (!this.dataList.length) {
          this.formValidate.page =
              this.formValidate.page == 1 ? 1 : this.formValidate.page - 1;
        }
        this.activityFrameList();
      }).catch((res) => {
        this.$Message.error(res.msg);
      });
    },
    onchangeIsShow (row) {
      activityFrameStatus(row.id,row.status).then(res=>{
        this.$Message.success(res.msg);
      }).catch(err=>{
        this.$Message.error(err.msg);
      })
    },
    //修改
    edit(id){
      console.log('rrr',id);
      this.$router.push({ path: "/admin/marketing/activity_frame/create/" + id });
    },
    //添加
    add() {
      this.$router.push({ path: "/admin/marketing/activity_frame/create/" + 0 });
    },
    // 边框列表
    activityFrameList() {
      activityFrameList(this.formValidate).then((res) => {
        this.dataList = res.data.list;
        this.total = res.data.count;
      });
    },
    pageChange(index) {
      this.formValidate.page = index;
      this.activityFrameList();
    },
    // 查询
    selChange() {
      this.formValidate.page = 1;
      this.activityFrameList();
    },
    reset() {
      this.formValidate = {
        name: "",
        status: "",
        time: "",
        create_time: "",
        page: 1
      };
      this.timeVal = [];
      this.dataTimeVal = [];
      this.activityFrameList();
    },
  },
};
